function hex_to_bytes(hex)
    local bytes = {}
    hex = hex:gsub("%s+", "")
    for i = 1, #hex - 1, 2 do
        local byte = tonumber(hex:sub(i, i+1), 16)
        if byte then table.insert(bytes, string.char(byte)) end
    end
    return table.concat(bytes)
end

function load_texture_from_hex(hex)
    local raw_data = hex_to_bytes(hex)
    if #raw_data > 0 then
        local ptr = ffi.cast("const void*", raw_data)
        local addr = tonumber(ffi.cast('uintptr_t', ptr))
        return imgui.CreateTextureFromFileInMemory(addr, #raw_data)
    end
    return nil
end

function CarregarTodas()
