function getKeyName(keycode)
    if keycode == key.VK_LBUTTON then
        return "MOUSE1"
    elseif keycode == key.VK_RBUTTON then
        return "MOUSE2"
    else
        return key.id_to_name(keycode) or "None"
    end
end

function TECLA(k)
    local dl = imgui.GetWindowDrawList()
    imgui.SetCursorPosY(imgui.GetCursorPosY() - 3)
    local pos = imgui.GetCursorScreenPos()
    local icon_w, total_h = 22, 20
    local key_name
    if binding and binding.key == k then
        key_name = (binding.text == "" or binding.text == "None") and "..." or binding.text
    else
        key_name = (settings.binds[k] and getKeyName(settings.binds[k])) or "None"
    end
    local text_size = imgui.CalcTextSize(key_name)
    local key_w = math.max(text_size.x + 14, 40)
    local total_w = icon_w + key_w

    imgui.PushStyleColor(imgui.Col.Button,        imgui.ImVec4(0,0,0,0))
    imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0,0,0,0))
    imgui.PushStyleColor(imgui.Col.ButtonActive,  imgui.ImVec4(0,0,0,0))
    if imgui.Button("##" .. k, imgui.ImVec2(total_w, total_h)) then
        if not (binding and binding.key == k) then
            binding = { key = k, last_upd = os.clock(), text = "..." }
        end
    end
    imgui.PopStyleColor(3)

    local isActive = binding and binding.key == k

    dl:AddRectFilled(
        imgui.ImVec2(pos.x, pos.y),
        imgui.ImVec2(pos.x + icon_w, pos.y + total_h),
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.12, 0.12, 0.12, 1.0))
    )

    dl:AddRectFilled(
        imgui.ImVec2(pos.x + icon_w, pos.y),
        imgui.ImVec2(pos.x + total_w, pos.y + total_h),
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.07, 0.07, 0.07, 1.0))
    )

    local borderCol
    if isActive then
        borderCol = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1.0, 1.0, 1.0, 1.0))
    else
        borderCol = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.25, 0.25, 0.25, 1.0))
    end
    dl:AddRect(
        imgui.ImVec2(pos.x, pos.y),
        imgui.ImVec2(pos.x + total_w, pos.y + total_h),
        borderCol, 3.0
    )
    dl:AddLine(
        imgui.ImVec2(pos.x + icon_w, pos.y + 1),
        imgui.ImVec2(pos.x + icon_w, pos.y + total_h - 1),
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.25, 0.25, 0.25, 1.0))
    )

    local icon_text = faicons.KEYBOARD ~= nil and faicons.KEYBOARD or "K"
    local icon_size = imgui.CalcTextSize(icon_text)
    dl:AddText(
        imgui.ImVec2(pos.x + (icon_w - icon_size.x) / 2, pos.y + (total_h - icon_size.y) / 2),
        0xFF888888, icon_text
    )
    dl:AddText(
        imgui.ImVec2(pos.x + icon_w + (key_w - text_size.x) / 2, pos.y + (total_h - text_size.y) / 2),
        0xFFCCCCCC, key_name
    )
end

