local tab_anim = {}

local function barratab(draw_list, win_pos, win_size)
    local ox = win_pos.x
    local oy = win_pos.y
    local h  = win_size.y
    local sidebar_w = 60
    local tab_w = sidebar_w
    local tab_h = 60
    local icon_area_h = #tabs * tab_h
    local start_y = oy + (h - icon_area_h) / 2
    local dt = imgui.GetIO().DeltaTime

    for i, tab in ipairs(tabs) do
        if tab_anim[i] == nil then tab_anim[i] = 0.0 end

        local is_active = (selected_tab == i)
        local speed = 8.0

        if is_active then
            tab_anim[i] = math.min(1.0, tab_anim[i] + dt * speed)
        else
            tab_anim[i] = math.max(0.0, tab_anim[i] - dt * speed)
        end

        local t = tab_anim[i]
        local ease = t * t * (3 - 2 * t)

        local tx = ox
        local ty = start_y + (i - 1) * tab_h
        local icon_y = ty + (tab_h - 16) / 2
        local rounding = 10
        local pad_x = 8
        local pad_y = 8
        local rx1 = tx + pad_x
        local ry1 = ty + pad_y
        local rx2 = tx + tab_w - pad_x
        local ry2 = ty + tab_h - pad_y

        if ease > 0.01 then
            draw_list:AddRectFilled(
                imgui.ImVec2(rx1 - 6 * ease, ry1 - 6 * ease),
                imgui.ImVec2(rx2 + 6 * ease, ry2 + 6 * ease),
                imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1.0, 1.0, 1.0, 0.04 * ease)), rounding + 4)
            draw_list:AddRectFilled(
                imgui.ImVec2(rx1 - 3 * ease, ry1 - 3 * ease),
                imgui.ImVec2(rx2 + 3 * ease, ry2 + 3 * ease),
                imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1.0, 1.0, 1.0, 0.07 * ease)), rounding + 2)
            draw_list:AddRectFilled(
                imgui.ImVec2(rx1, ry1),
                imgui.ImVec2(rx2, ry2),
                imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1.0, 1.0, 1.0, ease)), rounding)
        end

        imgui.SetCursorScreenPos(imgui.ImVec2(tx, ty))
        imgui.PushStyleColor(imgui.Col.Button,        imgui.ImVec4(0,0,0,0))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0,0,0,0))
        imgui.PushStyleColor(imgui.Col.ButtonActive,  imgui.ImVec4(0,0,0,0))
        if imgui.Button("##tab" .. i, imgui.ImVec2(tab_w, tab_h)) then
            selected_tab = i
        end
        imgui.PopStyleColor(3)

        if not is_active and imgui.IsItemHovered() then
            draw_list:AddRectFilled(
                imgui.ImVec2(rx1, ry1),
                imgui.ImVec2(rx2, ry2),
                imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1.0, 1.0, 1.0, 0.08)), rounding)
        end

        local icon_col_t = ease
        local r = 0.0 * icon_col_t
        local g = 0.0 * icon_col_t
        local b = 0.0 * icon_col_t
        local gray_v = 0.40
        local ir = r + gray_v * (1 - icon_col_t)
        local ig = g + gray_v * (1 - icon_col_t)
        local ib = b + gray_v * (1 - icon_col_t)

        imgui.SetCursorScreenPos(imgui.ImVec2(tx + (tab_w - 16) / 2, icon_y))
        imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(ir, ig, ib, 1.0))
        imgui.Text(faicons(tab.icon))
        imgui.PopStyleColor()
    end
end
function imgui.BeginTitleChild(str_id, size, rounding, offset, panelBool)
    rounding = rounding or 6

    if not _G.child_scroll_states then _G.child_scroll_states = {} end
    if not _G.child_scroll_states[str_id] then
        _G.child_scroll_states[str_id] = {current = 0, target = 0}
    end

    local dl = imgui.GetWindowDrawList()
    local pos = imgui.GetCursorScreenPos()
    local title = str_id:gsub("##.+$", "")
    local realW = size.x > 0 and size.x or imgui.GetContentRegionAvail().x
    local realH = size.y > 0 and size.y or imgui.GetContentRegionAvail().y

    dl:AddRectFilled(
        imgui.ImVec2(pos.x, pos.y),
        imgui.ImVec2(pos.x + realW, pos.y + realH),
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.09, 0.09, 0.09, 1.0)),
        rounding
    )

    local title_h = 28
    dl:AddRectFilled(
        imgui.ImVec2(pos.x + 1, pos.y + 1),
        imgui.ImVec2(pos.x + realW - 1, pos.y + title_h),
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.13, 0.13, 0.13, 1.0)),
        rounding
    )
    dl:AddRectFilled(
        imgui.ImVec2(pos.x + 1, pos.y + rounding),
        imgui.ImVec2(pos.x + realW - 1, pos.y + title_h),
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.13, 0.13, 0.13, 1.0)),
        0
    )
    dl:AddLine(
        imgui.ImVec2(pos.x, pos.y + title_h),
        imgui.ImVec2(pos.x + realW, pos.y + title_h),
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.18, 0.18, 0.18, 1.0)),
        1.0
    )

    should_pop_style = true
    imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0.0, 0.0, 0.0, 0.0))

    local flags = imgui.WindowFlags.NoScrollbar
    imgui.BeginChild(str_id, size, false, flags)

    local icon = title:match("^%S+") or ""
    local remaining = title:gsub("^%S+%s*", "")
    local text = remaining:match("^[^\n]+") or remaining
    local label = (icon ~= "" and text ~= "") and (icon .. " " .. text) or title

    imgui.SetCursorPosX(10)
    imgui.SetCursorPosY(imgui.GetCursorPosY() + 7)
    imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(1.0, 1.0, 1.0, 1.0))
    imgui.Text(label)
    imgui.PopStyleColor()

    imgui.SetCursorPosX(10)
    imgui.SetCursorPosY(imgui.GetCursorPosY() + 6)

    local scroll_state = _G.child_scroll_states[str_id]
    local io = imgui.GetIO()
    local wheel = io.MouseWheel
    
    if imgui.IsWindowHovered() and wheel ~= 0 and not io.WantCaptureKeyboard then
        scroll_state.target = scroll_state.target - wheel * 25
        local max_scroll = imgui.GetScrollMaxY()
        if scroll_state.target < 0 then scroll_state.target = 0 end
        if scroll_state.target > max_scroll then scroll_state.target = max_scroll end
    end
    
    scroll_state.current = scroll_state.current + (scroll_state.target - scroll_state.current) * 0.12
    imgui.SetScrollY(scroll_state.current)

    return true
end

function imgui.EndTitleChild()
    imgui.EndChild()
    if should_pop_style then
        imgui.PopStyleColor()
        should_pop_style = false
    end
end
function imgui.ToggleButton2(label, bool_ptr)
    if not UI_TOGGLE_ANIM then UI_TOGGLE_ANIM = {} end

    local draw_list = imgui.GetWindowDrawList()
    local pos = imgui.GetCursorScreenPos()
    local avail_w = imgui.GetContentRegionAvail().x
    local row_h = 22
    local pad_x = 10
    local result = imgui.InvisibleButton("##tog_" .. label, imgui.ImVec2(avail_w, row_h))
    local is_hovered = imgui.IsItemHovered()
    local anim_id = "tog_" .. label

    if UI_TOGGLE_ANIM[anim_id] == nil then
        UI_TOGGLE_ANIM[anim_id] = bool_ptr[0] and 1.0 or 0.0
    end

    local target = bool_ptr[0] and 1.0 or 0.0
    local t = UI_TOGGLE_ANIM[anim_id]
    t = t + (target - t) * 0.12
    if math.abs(t - target) < 0.002 then t = target end
    UI_TOGGLE_ANIM[anim_id] = t

    local tog_w, tog_h = 32, 16
    local tog_x = pos.x + avail_w - tog_w - 6
    local tog_y = pos.y + (row_h - tog_h) * 0.5
    local radius = tog_h * 0.5

    local bg = 0.14 + 0.08 * t
    draw_list:AddRectFilled(
        imgui.ImVec2(tog_x, tog_y),
        imgui.ImVec2(tog_x + tog_w, tog_y + tog_h),
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(bg, bg, bg, 1.0)),
        radius)

    local knob_r = radius - 3
    local knob_x = (tog_x + radius) + ((tog_x + tog_w - radius) - (tog_x + radius)) * t
    local knob_bright = 0.45 + 0.55 * t
    draw_list:AddCircleFilled(
        imgui.ImVec2(knob_x, tog_y + radius),
        knob_r,
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(knob_bright, knob_bright, knob_bright, 1.0)),
        16)

    local lbl_upper = label:upper()
    local lsz = imgui.CalcTextSize(lbl_upper)
    local lbl_col = bool_ptr[0] and
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1.0, 1.0, 1.0, 1.0)) or
        is_hovered and
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.55, 0.55, 0.55, 1.0)) or
        imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0.35, 0.35, 0.35, 1.0))

    draw_list:AddText(imgui.ImVec2(pos.x + pad_x, pos.y + (row_h - lsz.y) * 0.5), lbl_col, lbl_upper)

    if result then bool_ptr[0] = not bool_ptr[0] end
    return result
end
local function desenhaOlho(draw_list, cx, cy, eye_w, eye_h, tilt)
    local left   = imgui.ImVec2(cx - eye_w / 2, cy)
    local right  = imgui.ImVec2(cx + eye_w / 2, cy)
    local top    = imgui.ImVec2(cx + tilt, cy - eye_h / 2)
    local bottom = imgui.ImVec2(cx + tilt, cy + eye_h / 2)
    local white  = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(1, 1, 1, 1))

    draw_list:AddTriangleFilled(left, top, right, white)
    draw_list:AddTriangleFilled(left, right, bottom, white)

    local steps = 24
    local function arc(p1, ctrl, p2, col)
        local prev = p1
        for i = 1, steps do
            local t = i / steps
            local mt = 1 - t
            local x = mt*mt*p1.x + 2*mt*t*ctrl.x + t*t*p2.x
            local y = mt*mt*p1.y + 2*mt*t*ctrl.y + t*t*p2.y
            local cur = imgui.ImVec2(x, y)
            draw_list:AddTriangleFilled(imgui.ImVec2(cx, cy), prev, cur, col)
            prev = cur
        end
    end

    local bulge = 0.45
    local topCtrl    = imgui.ImVec2(cx + tilt, cy - eye_h * bulge)
    local bottomCtrl = imgui.ImVec2(cx + tilt, cy + eye_h * bulge)

    arc(left, topCtrl, right, white)
    arc(left, bottomCtrl, right, white)
end
local function sorrisoMacabro(draw_list, win_pos, win_size)
    local cx = win_pos.x + win_size.x / 2
    local cy = win_pos.y + 66

    local t = os.clock()

    local smile_w = 120
    local smile_h = 34 + math.sin(t * 4) * 2
    local steps = 40

    local left  = imgui.ImVec2(cx - smile_w / 2, cy - 3)
    local right = imgui.ImVec2(cx + smile_w / 2, cy - 3)
    local ctrl  = imgui.ImVec2(cx, cy + smile_h)

    local white = imgui.ColorConvertFloat4ToU32(
        imgui.ImVec4(1, 1, 1, 1)
    )

    local prev = left
    local pontos = {}

    for i = 0, steps do
        local p = i / steps
        local mt = 1 - p

        local x = mt*mt*left.x + 2*mt*p*ctrl.x + p*p*right.x
        local y = mt*mt*left.y + 2*mt*p*ctrl.y + p*p*right.y

        y = y + math.sin(t * 8 + i) * 0.8

        local cur = imgui.ImVec2(x, y)
        table.insert(pontos, cur)

        if i > 0 then
            draw_list:AddLine(prev, cur, white, 3)
        end

        prev = cur
    end

    for i = 3, #pontos - 3, 4 do
        local p = pontos[i]
        local toothTip = imgui.ImVec2(p.x, p.y + 10)

        draw_list:AddTriangleFilled(
            imgui.ImVec2(p.x - 3, p.y),
            imgui.ImVec2(p.x + 3, p.y),
            toothTip,
            white
        )
    end
end
local blinkTimer = 0

local function olhos(draw_list, win_pos, win_size)
    local cx = win_pos.x + win_size.x / 2
    local cy = win_pos.y + 30
    local eye_w = 46
    local gap = 28
    local tilt = 5

    local t = os.clock()

    local blink = math.max(0.15, math.abs(math.sin(t * 1.8)))

    local eye_h = 14 * blink

    desenhaOlho(
        draw_list,
        cx - (gap / 2 + eye_w / 2),
        cy,
        eye_w,
        eye_h,
        tilt
    )

    desenhaOlho(
        draw_list,
        cx + (gap / 2 + eye_w / 2),
        cy,
        eye_w,
        eye_h,
        -tilt
    )
end
