local particulas = {}
local mouse = { x = 0, y = 0, radius = 120 }

function initParticles()
    particulas = {}

    for i = 1, 70 do
        table.insert(particulas, {
            x = math.random(),
            y = math.random(),
            vx = (math.random() * 2 - 1) * 0.0015,
            vy = (math.random() * 2 - 1) * 0.0015,
            size = math.random(1, 3)
        })
    end
end

initParticles()

function PARTICULAS(draw_list, pos, size)
    local mx, my = getCursorPos()

    for _, p in ipairs(particulas) do
        if p.x > 1 or p.x < 0 then
            p.vx = -p.vx
        end
        if p.y > 1 or p.y < 0 then
            p.vy = -p.vy
        end

        local px = pos.x + p.x * size.x
        local py = pos.y + p.y * size.y

        if renderWindow[0] then
            local dx = mx - px
            local dy = my - py
            local dist = math.sqrt(dx * dx + dy * dy)

            if dist < mouse.radius then
                local force = (mouse.radius - dist) / mouse.radius
                p.x = p.x - (dx / size.x) * force * 0.02
                p.y = p.y - (dy / size.y) * force * 0.02
            end
        end

        p.x = p.x + p.vx
        p.y = p.y + p.vy

        draw_list:AddCircleFilled(
            imgui.ImVec2(px, py),
            p.size,
            0xAAFFFFFF
        )
    end

    for i = 1, #particulas do
        for j = i + 1, #particulas do
            local p1 = particulas[i]
            local p2 = particulas[j]

            local x1 = pos.x + p1.x * size.x
            local y1 = pos.y + p1.y * size.y
            local x2 = pos.x + p2.x * size.x
            local y2 = pos.y + p2.y * size.y

            local dx = x1 - x2
            local dy = y1 - y2
            local dist = dx * dx + dy * dy

            if dist < 12000 then
                local alpha = math.max(30, 255 - dist / 50)
                local color = bit.bor(bit.lshift(math.floor(alpha), 24), 0x00FFFFFF)

                draw_list:AddLine(
                    imgui.ImVec2(x1, y1),
                    imgui.ImVec2(x2, y2),
                    color,
                    1.0
                )
            end
        end
    end
end
local newFrame = imgui.OnFrame(
    function() return renderWindow[0] end,
