function main()
    while not isSampAvailable() do wait(100) end
    lua_thread.create(ESP2)
    lua_thread.create(FOVBOLA)
    lua_thread.create(Aimbot)
    pSpreadValue = memory.getfloat(9252452)
    lua_thread.create(XIT)
    while true do
        local menuKey = settings.binds["abrir_menu"]
        if menuKey then
            if wasKeyPressed(menuKey) then
                renderWindow[0] = not renderWindow[0]
            end
        else
            if wasKeyPressed(key.VK_X) then
                renderWindow[0] = not renderWindow[0]
            end
        end

        if binding then
            if os.clock() - binding.last_upd >= 0.4 then
                binding.text = (binding.text == "") and "..." or ""
                binding.last_upd = os.clock()
            end
            for i = 1, 255 do
                if wasKeyPressed(i) then
                    if i == key.VK_ESCAPE then
                        binding = nil
                    elseif i == key.VK_BACK then
                        settings.binds[binding.key] = nil
                        inicfg.save(settings, 'config')
                        binding = nil
                    else
                        settings.binds[binding.key] = i
                        inicfg.save(settings, 'config')
                        binding = nil
                    end
                    break
                end
            end
            if imgui.IsMouseClicked(0) then
                settings.binds[binding.key] = key.VK_LBUTTON
                inicfg.save(settings, 'config')
                binding = nil
            elseif imgui.IsMouseClicked(1) then
                settings.binds[binding.key] = key.VK_RBUTTON
                inicfg.save(settings, 'config')
                binding = nil
            end
        end

        wait(0)
    end
end
function Aimbot()
    while true do
        wait(0)
        if GUI.aimbot.Enable[0] and isKeyDown(VK_RBUTTON) then
            local playerID = GetNearestPed()
            if playerID ~= -1 then
                local _, handle = sampGetCharHandleBySampPlayerId(playerID)
                local targetBone = GUI.aimbot.boneIDs[GUI.aimbot.boneMode[0] + 1]
                local enX, enY, enZ = GetBodyPartCoordinates(targetBone, handle)
                if enX then
                    local canAim = true

                    if GUI.aimbot.checkvisible[0] then
                        local myX, myY, myZ = getCharCoordinates(PLAYER_PED)
                        local clearLine = isLineOfSightClear(
                            myX, myY, myZ,
                            enX, enY, enZ,
                            true, false, false, true, false, false, false
                        )
                        if not clearLine then canAim = false end
                    end

                    if canAim then
                        local cx, cy, cz = getActiveCameraCoordinates()
                        local vect = {
                            fX = cx - enX,
                            fY = cy - enY,
                            fZ = cz - enZ
                        }
                        local screenAspectRatio = representIntAsFloat(readMemory(0xC3EFA4, 4, false))
                        local crosshairOffset = {
                            representIntAsFloat(readMemory(0xB6EC10, 4, false)),
                            representIntAsFloat(readMemory(0xB6EC14, 4, false))
                        }
                        local mult = math.tan(getCameraFov() * 0.5 * 0.017453292)
                        local fz = math.pi - math.atan2(1.0, mult * ((0.5 - crosshairOffset[1]) * (2 / screenAspectRatio)))
                        local fx = math.pi - math.atan2(1.0, mult * 2 * (crosshairOffset[2] - 0.5))
                        local camMode = readMemory(0xB6F1A8, 1, false)
                        if not (camMode == 53 or camMode == 55) then
                            fx = math.pi / 2
                            fz = math.pi / 2
                        end
                        local ax = math.atan2(vect.fY, -vect.fX) - math.pi / 2
                        local az = math.atan2(math.sqrt(vect.fX * vect.fX + vect.fY * vect.fY), vect.fZ)
                        local angleX = fx - ax
                        local angleZ = az - fz
                        local view = {
                            fix(representIntAsFloat(readMemory(0xB6F258, 4, false))),
                            fix(representIntAsFloat(readMemory(0xB6F248, 4, false)))
                        }
                        local diffX = fix(angleX - view[1])
                        local diffZ = fix(angleZ - view[2])
                        local distance = math.sqrt(vect.fX^2 + vect.fY^2 + vect.fZ^2)
                        local smoothFactorX = 1.0 / math.max(1.0, GUI.aimbot.SmoothX[0])
                        local smoothFactorY = 1.0 / math.max(1.0, GUI.aimbot.SmoothY[0])
                        local moveX = diffX * smoothFactorX
                        local moveZ = diffZ * smoothFactorY
                        if distance > 30 then
                            local fov_adjustment = math.min(0.5, distance / 100)
                            setCameraPositionUnfixed(view[2] + moveZ * fov_adjustment, view[1] + moveX * fov_adjustment)
                        else
                            setCameraPositionUnfixed(view[2] + moveZ, view[1] + moveX)
                        end
                    end
                end
            end
        end
    end
end
function fix(angle)
    if angle > math.pi then
        angle = angle - (math.pi * 2)
    elseif angle < -math.pi then
        angle = angle + (math.pi * 2)
    end
    return angle
end

function GetNearestPed()
    local maxDistance = GUI.aimbot.Radius[0]
    local nearestPED = -1
    for i = 0, sampGetMaxPlayerId(true) do
        if sampIsPlayerConnected(i) then
            local find, handle = sampGetCharHandleBySampPlayerId(i)
            if find and isCharOnScreen(handle) and not isCharDead(handle) then
                local crosshairPos = {convertGameScreenCoordsToWindowScreenCoords(339.1, 179.1)}
                local targetBone = GUI.aimbot.boneIDs[GUI.aimbot.boneMode[0] + 1]
                local enX, enY, enZ = GetBodyPartCoordinates(targetBone, handle)
                if enX then
                    local sx, sy = convert3DCoordsToScreen(enX, enY, enZ)
                    if sx and sy then
                        local screenDist = math.sqrt((sx - crosshairPos[1])^2 + (sy - crosshairPos[2])^2)
                        if screenDist <= GUI.aimbot.FOV[0] then
                            local myX, myY, myZ = getCharCoordinates(PLAYER_PED)
                            local eX, eY, eZ = getCharCoordinates(handle)
                            local worldDist = math.sqrt((eX-myX)^2 + (eY-myY)^2 + (eZ-myZ)^2)
                            if worldDist < maxDistance then
                                nearestPED = i
                                maxDistance = worldDist
                            end
                        end
                    end
                end
            end
        end
    end
    return nearestPED
end
function GetBodyPartCoordinates(id, handle)
    if doesCharExist(handle) then
        local pedptr = getCharPointer(handle)
        local vec = ffi.new("float[3]")
        getbonePosition(ffi.cast("void*", pedptr), vec, id, true)
        return vec[0], vec[1], vec[2]
    end
end
