function XIT()
    while true do
        wait(0)
        if GUI.teste3[0] then
            memory.write(getCharPointer(PLAYER_PED) + 1376, 1132462080, 4, 0)
        else
            memory.write(getCharPointer(PLAYER_PED) + 1376, 1089470464, 4, 0)
        end
        if GUI.teste6[0] then
         if not isCharInAnyCar(PLAYER_PED) and not isCharInAir(PLAYER_PED) and isKeyDown(0x02) then
                while isKeyDown(0x02) do
                    wait(8)
                end
                local weapon = getCurrentCharWeapon(PLAYER_PED)
                local current = 0
                if weapon ~= -1 then
                    while true do
                        wait(10)
                        setCurrentCharWeapon(PLAYER_PED, 0)
                        wait(10)
                        current = getCurrentCharWeapon(PLAYER_PED)
                        if current == 0 or current == 1 then
                            break
                        end
                    end
                    setCurrentCharWeapon(PLAYER_PED, weapon)
                    wait(10)
                    setCurrentCharWeapon(PLAYER_PED, 0)
                    wait(10)
                    getCurrentCharWeapon(PLAYER_PED)
                end
            end
        end
        if GUI.teste5[0] then
			memory.setfloat(9252452, 0)
		else
			memory.setfloat(9252452, pSpreadValue)
		end
        if GUI.teste4[0] then
           local var_9_53 = raknetNewBitStream()
			raknetBitStreamWriteInt32(var_9_53, getCurrentCharWeapon(PLAYER_PED))
			raknetBitStreamWriteInt32(var_9_53, 0)
			raknetEmulRpcReceiveBitStream(22, var_9_53)
			raknetDeleteBitStream(var_9_53)
		end
    end
end
function FOVBOLA()
    while true do
        wait(0)

        if isSampAvailable() and GUI.aimbot.Enable[0] and GUI.aimbot.MOSTARFOVI[0] then
            local sw, sh = getScreenResolution()
            local cx, cy = sw / 2, sh / 2
            local radius = GUI.aimbot.FOV[0]
            local segments = 60

            for i = 0, segments - 1 do
                local angle1 = math.rad((i / segments) * 360)
                local angle2 = math.rad(((i + 1) / segments) * 360)

                local x1 = cx + math.cos(angle1) * radius
                local y1 = cy + math.sin(angle1) * radius
                local x2 = cx + math.cos(angle2) * radius
                local y2 = cy + math.sin(angle2) * radius

                renderDrawLine(x1, y1, x2, y2, 2, 0xFFFFFFFF)
            end
        end
    end
end
function ESP2()
    while true do
        wait(0)

        if isSampAvailable() and GUI.teste10[0] then
            local chars = getAllChars()
            local scrW, scrH = getScreenResolution()
            local lpx, lpy, lpz = getCharCoordinates(PLAYER_PED)
            local ox, oy = convert3DCoordsToScreen(lpx, lpy, lpz)

            for _, ped in ipairs(chars) do
                if ped ~= PLAYER_PED and doesCharExist(ped) then
                    local pid = sampGetPlayerIdByCharHandle(ped)
                    if pid and isCharOnScreen(ped) then
                        local px, py, pz = getCharCoordinates(ped)
                        local sx, sy = convert3DCoordsToScreen(px, py, pz)

                        if GUI.teste8[0] then
                            local head = { GetBodyPartCoordinates(8, ped) }
                            local feet = { GetBodyPartCoordinates(44, ped) }
                            if head[1] and feet[1] then
                                local top = { convert3DCoordsToScreen(head[1], head[2], head[3] + 0.2) }
                                local bot = { convert3DCoordsToScreen(feet[1], feet[2], feet[3] - 0.1) }
                                if top[1] and bot[1] then
                                    local height = bot[2] - top[2]
                                    if height > 0 then
                                        local half = height * 0.35
                                        local minX = top[1] - half
                                        local maxX = top[1] + half
                                        local minY = top[2]
                                        local maxY = bot[2]
                                        local t = 1.4
                                        renderDrawLine(minX, minY, maxX, minY, t, 0xFFFFFFFF)
                                        renderDrawLine(minX, maxY, maxX, maxY, t, 0xFFFFFFFF)
                                        renderDrawLine(minX, minY, minX, maxY, t, 0xFFFFFFFF)
                                        renderDrawLine(maxX, minY, maxX, maxY, t, 0xFFFFFFFF)
                                    end
                                end
                            end
                        end

                        if GUI.teste9[0] then
                            local head = { GetBodyPartCoordinates(8, ped) }
                            local feet = { GetBodyPartCoordinates(44, ped) }
                            if head[1] and feet[1] then
                                local top = { convert3DCoordsToScreen(head[1], head[2], head[3] + 0.2) }
                                local bot = { convert3DCoordsToScreen(feet[1], feet[2], feet[3] - 0.1) }
                                local hx, hy = convert3DCoordsToScreen(head[1], head[2], head[3] + 0.15)
                                if top[1] and bot[1] and hx then
                                    local height = bot[2] - top[2]
                                    local r = (height * 0.35) * 0.35
                                    if r > 2 then
                                        local segs = 32
                                        for i = 0, segs - 1 do
                                            local a1 = (i / segs) * math.pi * 2
                                            local a2 = ((i + 1) / segs) * math.pi * 2
                                            renderDrawLine(
                                                hx + math.cos(a1) * r,
                                                hy + math.sin(a1) * r,
                                                hx + math.cos(a2) * r,
                                                hy + math.sin(a2) * r,
                                                1.4, 0xFFFFFFFF
                                            )
                                        end
                                    end
                                end
                            end
                        end

                        if GUI.teste7[0] then
                            local dist = getDistanceBetweenCoords3d(lpx, lpy, lpz, px, py, pz)
                            if dist > 1.5 and isPointOnScreen(px, py, pz, 1) and sx and sy and sx > 0 and sx < scrW and sy > 0 and sy < scrH then
                                renderDrawLine(ox, oy, sx, sy, 1.3, 0xFFFFFFFF)
                            end
                        end
                    end
                end
            end
        end
    end
end
function GetBodyPartCoordinates(id, handle)
    if doesCharExist(handle) then
        local pedptr = getCharPointer(handle)
        local vec = ffi.new("float[3]")
        getBonePosition(ffi.cast("void*", pedptr), vec, id, true)
        return vec[0], vec[1], vec[2]
    end
end
